changeSet.sql:
delete from evenement_de_presence where type in ('PAUSE', 'REPRISE');

update journee_de_travail set etat = 'PRESENT' where etat = 'EN_PAUSE';

update journee_de_travail journee
set dernier_fait = (
  select max(evenement.date_de_survenue)
  from evenement_de_presence evenement
  where evenement.journee_id = journee.id and evenement.annulation_date is null
)
where journee.dernier_fait is distinct from (
  select max(evenement.date_de_survenue)
  from evenement_de_presence evenement
  where evenement.journee_id = journee.id and evenement.annulation_date is null
);
